import sys

def encode(array, length):
    result = 0
    for j in range(length):
        result = result * 3 + array[j]
    return result

def decode(array, length, code, base):
    for j in range(length - 1, -1, -1):
        array[j] = code % base
        code //= base

def main():
    input = sys.stdin.read().strip().split()
    n = int(input[0])
    m = int(input[1])
    if n < m:
        n, m = m, n
    p = 1
    for _ in range(m):
        p *= 3
    dp = [-1] * p
    dq = [-1] * p
    aa = [1] * m
    bb = [0] * m
    dp[encode(aa, m)] = 0
    index = 2
